local UIMazeStoryEventOptionNode = Class("UIMazeStoryEventOptionNode")
function UIMazeStoryEventOptionNode:__init() 
    self._data = nil
    self._ind = nil
    self._selectCb = nil
    --总共有俩种选项
    self.optionTab = {
        [1] = 1,
        [2] = 2,
    }

end

function UIMazeStoryEventOptionNode:__delete()
    self._data = nil
    self._ind = nil
    self._selectCb = nil
    self.optionTab = nil
end

function UIMazeStoryEventOptionNode:Awake()
    local tog = self.controller.transform:GetComponent(typeof(Toggle))
    SetToggleValueChanged(tog, Bind(self, self.OnSelect))
end

function UIMazeStoryEventOptionNode:Start()
end

function UIMazeStoryEventOptionNode:Refresh(data, index, selectCb)
    if not data then
        return
    end

    self._data = data
    self._selectCb = selectCb
    self._ind = checkNumber(index)

    local optionDes   --选项描述
    if self._ind == self.optionTab[1] then
        optionDes = data.bottonDesc1
        CfUtils.FillText(self.orderText, "A")
    else
        optionDes = data.bottonDesc2
        CfUtils.FillText(self.orderText, "B")
    end
    CfUtils.FillText(self.optionText, optionDes)

    KTool.SetActive(self.controller.gameObject, true)
end

function UIMazeStoryEventOptionNode:OnSelect(value)
    KTool.SetActive(self.chooseIma, value)

    if self._selectCb then
        self._selectCb(value)
    end
end

function UIMazeStoryEventOptionNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

